const dates={'SENIN':'2 November 2026','SELASA':'3 November 2026','RABU':'4 November 2026','KAMIS':'5 November 2026','JUMAT':'6 November 2026','SABTU':'7 November 2026'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function displayLink(v){if(!v)return '<span class="empty">—</span>';if(/^https:\/\/vt\.tokopedia\.com\/t\/[A-Za-z0-9_-]+\/?$/.test(v))return `<a class="link" href="${esc(v)}" target="_blank" rel="noopener noreferrer">Buka link produk ↗</a>`;return `<span class="instruction">${esc(v)}</span>`;}
